[Fact]
public async Task ExcludeFromCodeCoverageCanBeDisabled()
{
    const string source = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int Value { get; set; }
        }

        namespace MessagePack
        {
            [GeneratedMessagePackResolver(ExcludeFromCodeCoverage = false)]
            partial class GeneratedMessagePackResolver
            {
            }
        }
        """;

    IReadOnlyList<(string Path, string Text)> generated = await RunGeneratorAsync(source);

    Assert.NotEmpty(generated);
    foreach ((string path, string text) in generated)
    {
        Assert.False(
            text.Contains(ExcludeAttribute),
            $"Generated file '{path}' should not contain {ExcludeAttribute} when opted out.");
    }
}

